import requests

# Define the URL of the JSON server
json_server_url = 'http://example.com/json_server'

# Define a function to make GET requests to the server
def get_data():
    response = requests.get(json_server_url)
    if response.status_code == 200:
        return response.json()
    else:
        print("Failed to get data from the JSON server")
        return None

# Define a function to make POST requests to the server
def post_data(data):
    response = requests.post(json_server_url, json=data)
    if response.status_code == 201:
        return response.json()
    else:
        print("Failed to post data to the JSON server")
        return None

# Define a function to make PUT requests to the server
def put_data(data, id):
    url = f'{json_server_url}/{id}'
    response = requests.put(url, json=data)
    if response.status_code == 200:
        return response.json()
    else:
        print("Failed to put data to the JSON server")
        return None

# Define a function to make DELETE requests to the server
def delete_data(id):
    url = f'{json_server_url}/{id}'
    response = requests.delete(url)
    if response.status_code == 204:
        print("Data deleted successfully")
    else:
        print("Failed to delete data from the JSON server")

# Example usage of the functions

# Get data from the server
data = get_data()
print(data)

# Post data to the server
new_data = {"name": "John Doe", "age": 30}
response = post_data(new_data)
print(response)

# Put data to the server
updated_data = {"name": "Jane Doe", "age": 35}
id_to_update = 1
response = put_data(updated_data, id_to_update)
print(response)

# Delete data from the server
id_to_delete = 2
delete_data(id_to_delete)
